import { useCallback, useRef } from 'react';

import { useMemoStringify } from '@eventespresso/hooks';
import { useConfig, useTimeZoneTime } from '@eventespresso/services';
import { parseDate } from '@eventespresso/dates';
import { InlineDateRangePicker } from './InlineDateRangePicker';
import { InlineDateTimeInput } from './InlineDateTimeInput';

import './InlineDateRangeEdit.scss';

import type { DateRange } from '@eventespresso/dates';
import type { Datetime } from '@eventespresso/types';
import type { InlineDateTimeInputHandle } from './InlineDateTimeInput';

type DateOrString = string | Date;

export interface InlineDateRangeEditProps {
	date: DateOrString;
	dateField: Datetime.DateField;
	endDate: DateOrString;
	id: string;
	onChange: (dates: DateRange) => void;
	startDate: DateOrString;
}

export const InlineDateRangeEdit: React.FC<InlineDateRangeEditProps> = ({
	date,
	dateField,
	endDate,
	id,
	onChange,
	startDate,
}) => {
	const { formatForSite: format, utcToSiteTime } = useTimeZoneTime();
	const { dateTimeFormats, locale } = useConfig();
	const startDateInSiteTime = utcToSiteTime(parseDate(startDate));
	const endDateInSiteTime = utcToSiteTime(parseDate(endDate));

	const value = useMemoStringify<DateRange>([startDateInSiteTime, endDateInSiteTime]);
	const label = format(parseDate(date), dateTimeFormats.dateTimeFormat);

	const textInputRef = useRef<InlineDateTimeInputHandle>(null);

	const handleSameDateConfirmed = useCallback(() => {
		textInputRef.current?.resetInput();
	}, []);

	return (
		<div className='inline-date-edit-wrapper'>
			<InlineDateTimeInput
				ref={textInputRef}
				dateFormat={dateTimeFormats.dateTimeFormat}
				editing={dateField}
				id={id}
				onChange={onChange}
				range={value}
				value={label}
			/>
			<InlineDateRangePicker
				dateFormat={dateTimeFormats.dateTimeFormat}
				editing={dateField}
				id={id}
				locale={locale.user}
				onChange={onChange}
				onSameDateConfirmed={handleSameDateConfirmed}
				value={value}
			/>
		</div>
	);
};
