import { CalendarOutlined } from '@eventespresso/icons';
import { DateTimePicker, DateRangePickerLegend } from '@eventespresso/dates';
import { ButtonType, IconButton } from '../../../Button';
import { useInlineDateRangePicker } from './useInlineDateRangePicker';

import type { DateRange } from '@eventespresso/dates';
import type { Datetime } from '@eventespresso/types';

export interface InlineDateRangePickerProps {
	id: string;
	value: DateRange;
	onChange: (dates: DateRange) => void;
	onSameDateConfirmed?: () => void;
	locale: string;
	dateFormat: string;
	editing?: Datetime.DateField;
}

export const InlineDateRangePicker: React.FC<InlineDateRangePickerProps> = ({
	id,
	value,
	onChange,
	onSameDateConfirmed,
	locale,
	dateFormat,
	editing,
}) => {
	const { endDate, handleDateChange, isEditingStart, maxTime, minDate, minTime, onSave, selectedDate, startDate } =
		useInlineDateRangePicker({ id, value, onChange, onSameDateConfirmed, editing });

	return (
		<DateTimePicker
			customPicker={
				<IconButton
					borderless
					buttonType={ButtonType.MINIMAL}
					className='ee-edit-calendar-date-range-btn'
					color='black'
					icon={CalendarOutlined}
					size='small'
					disableOnFocus //Prevent Picker from opening on Tab key focus
				/>
			}
			dateFormat={dateFormat}
			endDate={endDate}
			fixedHeight
			locale={locale}
			maxTime={maxTime}
			minDate={minDate}
			minTime={minTime}
			onCalendarClose={onSave}
			onChange={handleDateChange}
			portalId='ee-inline-datepicker-portal'
			required={true}
			selectsEnd={!isEditingStart}
			selectsStart={isEditingStart}
			startDate={startDate}
			value={selectedDate}
		>
			<DateRangePickerLegend />
		</DateTimePicker>
	);
};
