import { forwardRef, useImperativeHandle } from 'react';

import { __ } from '@eventespresso/i18n';
import { InlineEditText } from '../../..';
import { useInlineDateTimeInput } from './useInlineDateTimeInput';

import type { DateRange } from '@eventespresso/dates';
import type { Datetime } from '@eventespresso/types';

export interface InlineDateTimeInputHandle {
	resetInput: () => void;
}

interface InlineDateTimeInputProps {
	dateFormat: string;
	editing?: Datetime.DateField;
	id: string;
	onChange: (dates: DateRange) => void;
	range: DateRange;
	value: string;
}

export const InlineDateTimeInput = forwardRef<InlineDateTimeInputHandle, InlineDateTimeInputProps>(
	({ dateFormat, editing, id, onChange, range, value }, ref) => {
		const { inlineMessage, inputValue, handleSubmit, resetInput } = useInlineDateTimeInput({
			dateFormat,
			editing,
			id,
			onChange,
			range,
			value,
		});

		useImperativeHandle(ref, () => ({ resetInput }), [resetInput]);

		return (
			<InlineEditText
				key={inputValue.version}
				hideEditIcon
				inlineMessage={inlineMessage}
				lineCount={1}
				onChange={handleSubmit}
				tag='div'
				tooltip={__('click to edit date and time…')}
				value={inputValue.value}
			/>
		);
	}
);
