import { useCallback, useEffect, useRef } from 'react';

import { DateFieldEnum } from '@eventespresso/types';
import { __ } from '@eventespresso/i18n';
import { useInlineInputMessage } from './context';

const END_DATE_ADJUSTED_DURATION_MS = 3000;

export const useEndDateAdjustedNotification = (id: string) => {
	const { setInputMessage } = useInlineInputMessage();
	const timerRef = useRef<ReturnType<typeof setTimeout>>(null);

	const endDateKey = `${id},${DateFieldEnum.End}`;

	const notifyEndDateAdjusted = useCallback(() => {
		clearTimeout(timerRef.current);
		setInputMessage(endDateKey, { type: 'info', message: __('End date has been adjusted') });
		timerRef.current = setTimeout(() => setInputMessage(endDateKey, null), END_DATE_ADJUSTED_DURATION_MS);
	}, [endDateKey, setInputMessage]);

	useEffect(() => () => clearTimeout(timerRef.current), []);

	return { notifyEndDateAdjusted };
};
