import classNames from 'classnames';

import { ErrorMessage, InfoMessage } from '../../InlineNotification';

import type { InlineInputMessageType } from '../..';

import './InlineInputMessage.scss';

interface InlineInputMessageProps {
	message: string;
	type?: InlineInputMessageType;
	className?: string;
}

export const InlineInputMessage: React.FC<InlineInputMessageProps> = ({ message, type = 'error', className }) => {
	const classes = classNames('ee-inline-notification-message', className);

	if (!message) return null;

	return (
		<div className={classes}>
			{type === 'error' ? <ErrorMessage message={message} /> : <InfoMessage message={message} />}
		</div>
	);
};
