import { useCallback, useEffect, useRef, useState } from 'react';
import { isEqual } from 'date-fns';

import { NOW } from '@eventespresso/constants';
import { isOnOrBeforeDate, setTimeToJustBeforeZeroHour } from '@eventespresso/dates';
import { DateFieldEnum } from '@eventespresso/types';
import { useAdjustedDateRange } from '../../../DateTimeRangePicker';
import { useEndDateAdjustedNotification } from '../useEndDateAdjustedNotification';

import type { DateRange } from '@eventespresso/dates';
import type { Datetime } from '@eventespresso/types';

const justBeforeZeroHour = setTimeToJustBeforeZeroHour(NOW);

interface UseInlineDateRangePickerProps {
	id: string;
	value: DateRange;
	editing?: Datetime.DateField;
	onChange: (dates: DateRange) => void;
	onSameDateConfirmed?: () => void;
}

export const useInlineDateRangePicker = ({
	id,
	value,
	editing,
	onChange,
	onSameDateConfirmed,
}: UseInlineDateRangePickerProps) => {
	const oldStartDate = value?.[0] || null;
	const oldEndDate = value?.[1] || null;

	const [dateRange, setDateRange] = useState<{ startDate: Date; endDate: Date }>({
		startDate: oldStartDate || NOW,
		endDate: oldEndDate || NOW,
	});
	const { startDate, endDate } = dateRange;

	// Tracks whether the user selected a date during the current picker session.
	// Used to distinguish an actual selection from simply closing the picker.
	const datePickedRef = useRef(false);

	const handleChangeDate = useCallback((newValue: DateRange) => {
		setDateRange({ startDate: newValue?.[0], endDate: newValue?.[1] });
	}, []);

	const { notifyEndDateAdjusted } = useEndDateAdjustedNotification(id);

	useAdjustedDateRange({
		dates: [startDate, endDate],
		setDates: handleChangeDate,
		enforceDatesInOrder: true,
	});

	useEffect(() => {
		handleChangeDate(value);
	}, [value, handleChangeDate]);

	const onSave = useCallback(() => {
		const datePicked = datePickedRef.current;
		datePickedRef.current = false;

		if (!datePicked) return;

		// Trigger the mutation even when the selected date hasn't changed
		// so the user still receives update feedback.
		onChange([startDate, endDate]);

		if (editing === DateFieldEnum.Start && oldEndDate && !isEqual(oldEndDate, endDate)) {
			notifyEndDateAdjusted();
		}

		// If the selected date range hasn't changed, the entity won't update
		// and the input effect won't run. Notify the parent so it can reset
		// the input state and clear any stale errors.
		if (isEqual(oldStartDate, startDate) && isEqual(oldEndDate, endDate)) {
			onSameDateConfirmed?.();
		}
	}, [editing, oldStartDate, oldEndDate, startDate, endDate, onChange, onSameDateConfirmed, notifyEndDateAdjusted]);

	const handleDateChange = useCallback(
		(date: Date) => {
			datePickedRef.current = true;
			setDateRange((prev) => ({
				...prev,
				[editing]: date,
			}));
		},
		[editing]
	);

	const isEditingStart = editing === DateFieldEnum.Start;
	const limitEndByStart = editing === DateFieldEnum.End;
	const isOnSameDay = isOnOrBeforeDate(endDate, startDate, false);

	const minTime = limitEndByStart && isOnSameDay ? startDate : undefined;
	const maxTime = limitEndByStart && isOnSameDay ? justBeforeZeroHour : undefined;
	const minDate = limitEndByStart ? startDate : undefined;

	return {
		startDate,
		endDate,
		editing,
		selectedDate: dateRange[editing],
		handleDateChange,
		onSave,
		isEditingStart,
		minTime,
		maxTime,
		minDate,
	};
};
