import { useCallback, useEffect, useMemo, useState } from 'react';
import { parse, isValid, isEqual, isBefore } from 'date-fns';

import { mayBeAdjustEndDate } from '@eventespresso/dates';
import { DateFieldEnum } from '@eventespresso/types';
import { __ } from '@eventespresso/i18n';
import { useInlineInputMessage } from '..';
import { useEndDateAdjustedNotification } from '../useEndDateAdjustedNotification';

import type { DateRange } from '@eventespresso/dates';
import type { Datetime } from '@eventespresso/types';
import type { InlineInputMessageType } from '../..';

const DATE_FORMATS: string[] = [
	'MM-dd-yyyy h:mm a',
	'yyyy-MM-dd h:mm a',
	'MM/dd/yyyy h:mm a',
	'yyyy/MM/dd h:mm a',
	'M-d-yyyy h:mm a',
	'yyyy-M-d h:mm a',
	'MM-dd-yyyy HH:mm',
	'yyyy-MM-dd HH:mm',
];

/**
 * Returns a fresh timestamp on each call for use as a unique version key,
 * forcing React to remount input component when the key changes.
 */
const getTimestamp = (): number => Date.now();

const tryParseDate = (input: string, formats: string[]): Date | null => {
	for (const format of formats) {
		const parsed = parse(input, format, new Date());
		if (isValid(parsed)) {
			return parsed;
		}
	}
	return null;
};

const validateEndAfterStart = (startDate: Date | null, endDate: Date | null): boolean =>
	!!startDate && !!endDate && !isBefore(endDate, startDate);

interface UseInlineDateTimeInputProps {
	id: string;
	value: string;
	editing?: Datetime.DateField;
	range: DateRange;
	dateFormat: string;
	onChange: (dates: DateRange) => void;
}

export const useInlineDateTimeInput = ({
	dateFormat,
	id,
	value,
	editing,
	range,
	onChange,
}: UseInlineDateTimeInputProps) => {
	const { inputMessages, setInputMessage } = useInlineInputMessage();
	const { notifyEndDateAdjusted } = useEndDateAdjustedNotification(id);

	// Include version to force re-render even when resetting to same value.
	// Useful for resetting input on error without relying on value change.
	const [inputValue, setInputValue] = useState({ value, version: getTimestamp() });

	const messageKey = useMemo(() => `${id},${editing}`, [id, editing]);
	const inlineMessage = useMemo(() => inputMessages[messageKey] || null, [inputMessages, messageKey]);

	useEffect(() => {
		setInputValue({ value, version: getTimestamp() });
		if (inlineMessage?.type === 'error') {
			clearMessage();
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [value]);

	const dateFormats = useMemo(() => [...DATE_FORMATS, dateFormat], [dateFormat]);

	const showMessage = useCallback(
		(type: InlineInputMessageType, message: string | null, field = editing) => {
			const key = `${id},${field}`;
			if (message === null) {
				setInputMessage(key, null);
			} else {
				setInputMessage(key, { type, message });
			}
		},
		[editing, id, setInputMessage]
	);

	const clearMessage = useCallback(() => {
		setInputMessage(messageKey, null);
	}, [messageKey, setInputMessage]);

	// Resets the input to the last saved value and clears any messages.
	// Exposed through useImperativeHandle so the date picker can restore
	// the input after an invalid entry when the same date is reselected.
	const resetInput = useCallback(() => {
		setInputValue({ value, version: getTimestamp() });
		clearMessage();
	}, [value, clearMessage]);

	const handleSubmit = useCallback(
		(userInput) => {
			if (!userInput) {
				resetInput();
				return;
			}

			const parsedDate = tryParseDate(userInput, dateFormats);

			if (!parsedDate) {
				showMessage('error', `${__('Invalid date:')} ${userInput}`);
				return;
			}

			let updatedRange: DateRange = [...range];

			if (editing === DateFieldEnum.Start) {
				const newStartDate = parsedDate;
				const newEndDate = mayBeAdjustEndDate({
					newStartDate,
					newEndDate: range[1],
					prevStartDate: range[0],
					prevEndDate: range[1],
				});

				if (newEndDate !== range[1]) {
					notifyEndDateAdjusted();
				}

				updatedRange = [newStartDate, newEndDate];
			} else if (editing === DateFieldEnum.End) {
				const [startDate] = range;
				if (!validateEndAfterStart(startDate, parsedDate)) {
					showMessage('error', __('End date and time cannot be before start date and time.'));
					return;
				}
				updatedRange = [range[0], parsedDate];
			}

			const [startDate, endDate] = updatedRange;

			if (!isEqual(range[0], startDate) || !isEqual(range[1], endDate)) {
				onChange([startDate, endDate]);
				clearMessage();
			} else {
				resetInput();
			}
		},
		[dateFormats, editing, range, clearMessage, onChange, showMessage, notifyEndDateAdjusted, resetInput]
	);

	return {
		inlineMessage,
		inputValue,
		handleSubmit,
		resetInput,
	};
};
