import { createContext, useContext, useState, useMemo, useCallback } from 'react';
import invariant from 'invariant';

import type { ReactNode, FC } from 'react';
import type { InlineMessage } from '../..';

export interface InlineInputMessage extends InlineMessage {
	id?: string;
}

interface ContextValue {
	inputMessages: Record<string, InlineInputMessage | null>;
	setInputMessage: (id: string, notification: InlineInputMessage | null) => void;
}

const InlineInputMessageContext = createContext<ContextValue | undefined>(undefined);

export const InlineInputMessageProvider: FC<{ children: ReactNode }> = ({ children }) => {
	const [inputMessages, setInputMessages] = useState<Record<string, InlineInputMessage | null>>({});
	const setInputMessage = useCallback((id: string, notification: InlineInputMessage | null) => {
		setInputMessages((prev) => {
			if (notification === null) {
				const { [id]: ignored, ...rest } = prev;
				return rest;
			}
			return { ...prev, [id]: { ...notification, id } };
		});
	}, []);

	const contextValue = useMemo(() => ({ inputMessages, setInputMessage }), [inputMessages, setInputMessage]);

	return <InlineInputMessageContext.Provider value={contextValue}>{children}</InlineInputMessageContext.Provider>;
};

export const useInlineInputMessage = () => {
	const state = useContext(InlineInputMessageContext);
	invariant(state, 'useInlineInputMessage must be used within InlineInputMessageProvider');
	return state;
};
