import classNames from 'classnames';

import { Dotdotdot } from '@eventespresso/adapters';
import { Edit } from '@eventespresso/icons';
import { TabbableText } from '../../';
import { InlineInputMessage } from './InlineInputMessage';

import type { PreviewProps } from './types';

import './style.scss';

const Preview: React.FC<PreviewProps> = ({
	'aria-describedby': ariaDescribedby,
	className,
	hideEditIcon,
	inlineMessage,
	isDisabled,
	isEditing,
	lineCount,
	lineLength = 25,
	onRequestEdit,
	tooltip,
	value,
}) => {
	if (isEditing) {
		return null;
	}

	const icon = !(isDisabled || hideEditIcon) ? <Edit className='ee-inline-edit__edit-icon' /> : null;
	const isError = inlineMessage?.type === 'error';
	const previewClassName = classNames('ee-inline-edit__preview', className, {
		'ee-inline-edit__preview--error': isError,
	});

	let textInput: string | JSX.Element = value;

	if (lineCount && String(value)?.length > lineLength) {
		textInput = <Dotdotdot clamp={lineCount}>{value}</Dotdotdot>;
	}

	return (
		<div className='ee-inline-edit__preview-wrapper'>
			{inlineMessage && <InlineInputMessage {...inlineMessage} />}
			<TabbableText
				aria-describedby={ariaDescribedby}
				className={previewClassName}
				icon={icon}
				onClick={onRequestEdit}
				isDisabled={isDisabled}
				text={textInput}
				tooltip={tooltip}
			/>
		</div>
	);
};

export default Preview;
