import { useEffect, useState } from 'react';
import { isEqual } from 'date-fns';

import { mayBeAdjustEndDate } from '@eventespresso/dates';
import { usePrevious } from '@eventespresso/hooks';

import type { DateRange } from '@eventespresso/dates';

interface UseAdjustedDateRangeOptions {
	dates: DateRange;
	setDates?: (dates: DateRange) => void;
	enforceDatesInOrder?: boolean;
}

export const useAdjustedDateRange = ({ dates, setDates, enforceDatesInOrder = false }: UseAdjustedDateRangeOptions) => {
	const [computedEndDate, setComputedEndDate] = useState<Date | null>(null);
	const previousDates = usePrevious(dates);

	useEffect(() => {
		const areValidDates = Array.isArray(dates) && dates.length === 2;
		if (!enforceDatesInOrder || !previousDates || !areValidDates) return;

		const [startDate, endDate] = dates;
		const [prevStartDate, prevEndDate] = previousDates;

		const startDateChanged = !isEqual(startDate, prevStartDate);

		if (startDateChanged) {
			const newEndDate = mayBeAdjustEndDate({
				newStartDate: startDate,
				newEndDate: endDate,
				prevStartDate,
				prevEndDate,
			});

			if (!isEqual(newEndDate, endDate)) {
				setDates && setDates([startDate, newEndDate]);
				setComputedEndDate(newEndDate);
			} else {
				setComputedEndDate(null);
			}
		}
	}, [dates, enforceDatesInOrder, previousDates, setDates]);

	return {
		computedEndDate,
	};
};
